bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
printf 'ACTIVE_IMAGE=%s\n' "$(docker inspect "$cid" --format '{{.Config.Image}}')"
printf 'ACTIVE_RUNNING=%s\n' "$(docker inspect "$cid" --format '{{.State.Running}}')"
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';import pg from 'pg';
const e=process.env;const p=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,
database:e.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1});
try{
const a=(await p.query("SELECT to_regclass('videobot_rich_offer_receipts') IS NOT NULL AS table_exists, (SELECT count(*)::int FROM videobot_stars_ledger WHERE kind='paid') AS paid_count")).rows[0];
console.log('AFTER_FAILED_DEPLOY='+JSON.stringify(a));
}finally{await p.end()}
NODE
printf 'READY_CODE_MARKERS:'
docker logs "$cid" 2>&1 | grep -Eo '(CREATOR_DM_POLL_READY=PASS|STICKER_SHOP_HTTP_READY=PASS|CREATOR_MIGRATION_[A-Z_]+|VIDEO_[A-Z_]+_READY=PASS)' | sort -u | tr '\n' ' '
printf '\n'
